CREATE TABLE EMPLOYEE (
    EMPID INT PRIMARY KEY,
    NAME VARCHAR,
    SUPERVISOR INT,
    SALARY INT
);

CREATE TABLE BONUS (
    EMPID INT PRIMARY KEY,
    BONUS INT,
    FOREIGN KEY (EMPID) REFERENCES EMPLOYEE (EMPID)
);

counterexample:
-- No INSERT statements can be provided that yield different outputs because under the provided schema Q1 and Q2 are equivalent.
-- For example, consider the following test data which will yield the same results in both queries:

INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (1, 'Alice', NULL, 50000);
INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY) VALUES (2, 'Bob', 1, 60000);

INSERT INTO BONUS (EMPID, BONUS) VALUES (2, 900);
-- In Q1 and Q2, 'Alice' (with no BONUS row) yields BONUS as NULL and qualifies, and 'Bob' qualifies because 900 < 1000.

-- Thus, no counterexample exists under the given schema.

