schema:
CREATE TABLE VIEWS (
    ARTICLE_ID INT,
    AUTHOR_ID INT,
    VIEWER_ID INT,
    VIEW_DATE DATE
);

counterexample:
-- No counterexample exists since Q1 and Q2 are equivalent.
-- (Inserting any valid test rows under the schema will yield the same result in both queries.)

-- For instance, the following INSERTs illustrate how qualifying data would be processed equivalently:
INSERT INTO VIEWS (ARTICLE_ID, AUTHOR_ID, VIEWER_ID, VIEW_DATE) VALUES (1, 100, 10, '2020-01-01');
INSERT INTO VIEWS (ARTICLE_ID, AUTHOR_ID, VIEWER_ID, VIEW_DATE) VALUES (2, 101, 10, '2020-01-01');
INSERT INTO VIEWS (ARTICLE_ID, AUTHOR_ID, VIEWER_ID, VIEW_DATE) VALUES (1, 100, 20, '2020-01-02');
INSERT INTO VIEWS (ARTICLE_ID, AUTHOR_ID, VIEWER_ID, VIEW_DATE) VALUES (2, 101, 20, '2020-01-03');

-- In this example, viewer 10 qualifies (because they viewed 2 distinct articles on 2020-01-01) and both Q1 and Q2 return 10. Viewer 20 never qualifies on any single day so they are excluded in both cases.

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'S8', 700);

INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'IPHONE', 1000);

INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 10, 100, '2023-10-01', 1, 700);

INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 20, NULL, '2023-10-02', 1, 1000);

-- The following INSERT statements create test data that would demonstrate a difference in behavior if duplicate logins on the same day were allowed. 
-- (Note: This counterexample violates the declared primary key constraint, but it shows the situation where Q1 and Q2 would produce different results if a player could have multiple sessions per day.)

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 100, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 3);

-- Player 2 has a first login on 2023-01-01 and then two logins on 2023-01-02 (duplicate day, which under the current PK is not allowed)
-- The following two INSERTs for player 2 would normally be rejected by the PK constraint. They are shown here solely to illustrate the counterexample logic.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-01', 200, 4);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-02', 201, 6);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-02', 202, 2);

-- Under a relaxed schema that permits multiple rows per player per day, Q1’s join would yield a numerator of 1 (from player 1) + 2 (from player 2) = 3, while the denominator would be counted as 2 players. Q2 would sum the two target logins from player 2 as well, resulting in a fraction of 1.50. However, if the intended measure was the fraction of players returning (i.e. a boolean per player), one might expect 1.00 (since both players returned at least once).

-- Under the current schema, no valid counterexample exists because the primary key (PLAYER_ID, EVENT_DATE) ensures at most one row per player per day.

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 1, 10);
-- The following two INSERTs create duplicate activity events for PLAYER_ID = 1 on '2021-01-02'. Under the declared primary key these would be rejected, but they serve here as a counterexample to show the difference in Q1 and Q2 when duplicate next‐day events occur.
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 1, 20);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 2, 30);

INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-02-01', 1, 15);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-02-03', 1, 25);

