CREATE TABLE CUSTOMER (
    ID INT PRIMARY KEY,
    NAME VARCHAR,
    REFEREE_ID INT,
    FOREIGN KEY (REFEREE_ID) REFERENCES CUSTOMER(ID)
);

counterexample:
-- No INSERT statements can create a discrepancy between Q1 and Q2.
-- For example, consider the following test data which, when inserted, yield the same results for both queries:

INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (1, 'Alice', NULL);
-- To satisfy the foreign key, insert a customer with ID=2
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (2, 'Bob', NULL);
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (3, 'Charlie', 1);
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (4, 'David', 2);

-- In this data:
-- • 'Alice': REFEREE_ID IS NULL, so Q1 returns her and Q2 also returns her (IFNULL(NULL,0)=0, and 0 <> 2).
-- • 'Bob': REFEREE_ID IS NULL, included by both queries.
-- • 'Charlie': REFEREE_ID = 1 (which is not 2), included by both.
-- • 'David': REFEREE_ID = 2, excluded by both.

-- As illustrated, both queries produce the same result set. Thus, no counterexample exists.

