CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR,
    FOLLOWER VARCHAR,
    PRIMARY KEY (FOLLOWEE, FOLLOWER)
);

counterexample:
-- No counterexample exists. For instance, the following test data:

INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A','B');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('B','A');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A','C');

produces 
-- Q1: GROUP BY FOLLOWEE gives: A → 2, B → 1 (since both A and B appear as followers)
-- Q2: GROUP BY R.FOLLOWER gives: A → 2, B → 1
so both queries return the same results.

-- Any INSERTs satisfying the schema yield equivalent outputs for Q1 and Q2.

-- NOTE: This counterexample assumes that the primary key constraint on (PLAYER_ID, EVENT_DATE) is relaxed so that a player can have more than one row with the same EVENT_DATE.

-- Player 1: First login on 2020-01-01; two different activity rows on 2020-01-02 (i.e. the day after):
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 100, 10);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 101, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-02', 102, 8);

-- Player 2: First login on 2020-01-01; one login on 2020-01-02 (consecutive):
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-01', 200, 12);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2020-01-02', 201, 7);

/*
For this data set:

  • For player 1:
      • The derived TEMP table (first logins) gives MIN_DATE = '2020-01-01'.
      • The join finds two rows on '2020-01-02' so Q1 sums 2 for player 1.
      • In the inner window query for Q2, the two logins for player 1 are sorted. Even though there are two rows on 2020-01-02, only one of them will be assigned as the second login (using RANK() or ROW_NUMBER()); hence Q2 counts 1 for player 1.

  • For player 2 both queries count a 1 because there is only one login on 2020-01-02.

Thus, Q1 computes a fraction of (2+1)/2 = 1.5 while Q2 computes (1+1)/2 = 1.0. After rounding, the final displayed FRACTION values differ.
*/

