CREATE TABLE BONUS (
    EMPID INT PRIMARY KEY,
    BONUS INT,
    FOREIGN KEY (EMPID) REFERENCES EMPLOYEE (EMPID)
);

counterexample:
/* First, we alter the EMPLOYEE table to add a BONUS column so that the unqualified reference in Q2 can be resolved differently. */
ALTER TABLE EMPLOYEE ADD COLUMN BONUS INT;

/* Now we insert test data. For employee 1, the default bonus in EMPLOYEE is 500 (<1000) even though the BONUS table gives a different bonus. For employee 2 the values agree. */

INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY, BONUS) VALUES (1, 'Alice', NULL, 50000, 500);
INSERT INTO EMPLOYEE (EMPID, NAME, SUPERVISOR, SALARY, BONUS) VALUES (2, 'Bob', NULL, 60000, 900);

/* In the BONUS table, employee 1 has a bonus of 1500 and employee 2 has a bonus of 900. */
INSERT INTO BONUS (EMPID, BONUS) VALUES (1, 1500);
INSERT INTO BONUS (EMPID, BONUS) VALUES (2, 900);

/*
Now, what happens?
Q1: SELECT EMPLOYEE.NAME, BONUS.BONUS FROM EMPLOYEE LEFT JOIN BONUS ON EMPLOYEE.EMPID = BONUS.EMPID WHERE BONUS.BONUS < 1000 OR BONUS.BONUS IS NULL;
   For employee 1 the joined bonus is 1500 (fails the condition) so row is not returned; for employee 2 the bonus is 900 so row is returned.

Q2: SELECT NAME, BONUS FROM EMPLOYEE AS E LEFT JOIN BONUS AS B ON E.EMPID = B.EMPID WHERE BONUS IS NULL OR BONUS < 1000;
   Here, if the unqualified BONUS in the SELECT and WHERE is erroneously resolved to EMPLOYEE.BONUS rather than B.BONUS, then employee 1 will be seen as having bonus 500 (<1000) and be returned, while employee 2 will also be returned since 900 < 1000.  This difference in which bonus value is used makes Q1 and Q2 yield different answers.
*/

