INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-01', 100, 5);
-- Player 1 has two follow-up activities on 2021-01-02
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 101, 4);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2021-01-02', 102, 6);

-- Player 2 has only one activity so no follow-up event
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2021-01-03', 103, 2);

-- Under these circumstances:
-- In Q1, the join for player 1 yields two rows that meet the condition so its numerator adds 2, whereas player 2 adds 0. With 2 players, Q1 returns ROUND(2/2, 2) = 1.00.
-- In Q2, the inner join returns two rows for player 1 but if we were intending to count a player only once then one might expect a fraction of 0.50. (Depending on how the analytic intent is interpreted, Q2 might be modified to count DISTINCT players, but as written it counts join rows.)

-- Note: This counterexample requires relaxing the PK on (PLAYER_ID, EVENT_DATE) so that a player can have multiple records on the same day.

