INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-01', 101, 5);
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2023-01-02', 101, 3);
-- Player 2 is known to have installed on 2023-01-01 (say, via an ETL process) but his day1 record was removed from ACTIVITY; so only an install record exists in the installation source
-- In our counterexample we simulate this effect by not having any ACTIVITY row with a date matching player 2’s install+1 (and assuming that in the full pipeline his install still appears in the subquery)
INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (2, '2023-01-01', 102, 4);
-- Note: In a strictly enforced ACTIVITY table the install row is always present and would join to itself. However, in an ETL process the installation date might be computed from a staging view that includes players that later lose their day+1 record. 

/* When running Q1 the inner join forces player 2 to join only his 2023-01-01 row, and since 2023-01-01+1 = 2023-01-02 does not equal 2023-01-01, player 2’s record does not contribute a retention hit and (depending on implementation) might be dropped from aggregation. In contrast, Q2’s LEFT JOIN will include player 2 with a NULL for the day1 activity, thus counting him as an install with 0 retention. This difference in the set of players being aggregated can lead to a different overall retention rate. */

