-- No INSERT statements can produce a counterexample because under the declared schema, Q1 and Q2 are equivalent.
-- For example, even if we try the following data, both queries return the same result:

INSERT INTO CINEMA VALUES (1, 1);
INSERT INTO CINEMA VALUES (2, 1);
