CREATE TABLE MYNUMBERS (
    NUM INT
);

counterexample:
-- There is no counterexample that produces a disagreement between Q1 and Q2 under the given schema.
-- For example, consider the test data below; both queries return 4.

INSERT INTO MYNUMBERS (NUM) VALUES (1);
INSERT INTO MYNUMBERS (NUM) VALUES (2);
INSERT INTO MYNUMBERS (NUM) VALUES (2);
INSERT INTO MYNUMBERS (NUM) VALUES (3);
INSERT INTO MYNUMBERS (NUM) VALUES (3);
INSERT INTO MYNUMBERS (NUM) VALUES (4);

-- Q1:
--   SELECT MAX(NUM) FROM (SELECT NUM FROM MYNUMBERS GROUP BY NUM HAVING COUNT(NUM)=1) AS T;
-- returns 4

-- Q2:
--   WITH T AS (SELECT COUNT(NUM) AS CNT, NUM FROM MYNUMBERS GROUP BY NUM)
--   SELECT MAX(T.NUM) FROM MYNUMBERS M LEFT JOIN T ON T.NUM = M.NUM AND T.CNT =1;
-- also returns 4

-- Thus, given the schema and the operations involved, no counterexample exists.

