INSERT INTO MYNUMBERS (NUM) VALUES (NULL);
INSERT INTO MYNUMBERS (NUM) VALUES (3);
INSERT INTO MYNUMBERS (NUM) VALUES (3);
INSERT INTO MYNUMBERS (NUM) VALUES (7);

