-- (b) the CUSTOMER table is actually a transactional table (i.e. it can have multiple rows for the same CUSTOMER_ID),
-- so that we can observe the difference between COUNT(DISTINCT PRODUCT_KEY) and COUNT(*).

-- Insert duplicate rows into PRODUCT so that there is a duplicate product key:
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (1);  -- duplicate row
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (2);

