INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (100, 2);

-- Under these insertions:
-- The subquery in Q1 returns COUNT(DISTINCT PRODUCT_KEY) = 2 from PRODUCT, and customer 100 has COUNT(DISTINCT PRODUCT_KEY)=2 so Q1 returns customer 100.
-- The subquery in Q2 returns COUNT(*) = 3 from PRODUCT, so customer 100 fails the condition (2 <> 3) and is not returned.

