-- (Assume that for the purpose of testing the behavior the foreign-key check is temporarily turned off so that SALES may reference a nonexistent product.)

-- Insert two products: one for S8 and one for IPHONE.
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'S8', 500);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'IPHONE', 1000);

-- Insert a valid S8 sale (buyer 1 bought an S8).
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (1, 10, 1, '2023-01-01', 1, 500);

-- Insert a valid IPHONE sale (buyer 2 bought an IPHONE); this row will appear in both subqueries.
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (2, 20, 2, '2023-01-02', 1, 1000);

-- Insert an “orphan” IPHONE sale: its PRODUCT_ID (3) does not exist in PRODUCT.
-- In Q1 the inner join drops this row so it does not contribute a buyer value;
-- In Q2 the left join produces a row with NULL in the product columns, but because of the WHERE clause
-- (P.PRODUCT_NAME = 'IPHONE'), this row still appears in the subquery – in many SQL systems it ends up contributing a NULL value to the set.
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) 
VALUES (3, 30, 3, '2023-01-03', 1, 1000);

/* Expected behavior:
   • Q1 (with inner join in its subquery) sees only the valid IPHONE sale so its subquery returns {2}, and since buyer 1 is not in {2} the S8 sale qualifies and Q1 returns buyer 1.
   • Q2 (with left join in its subquery) sees the valid IPHONE sale and also the orphan sale (which yields a NULL in the join), so its subquery returns something like {2, NULL}.
     Because x NOT IN (2, NULL) evaluates to UNKNOWN for any non‐NULL x, Q2 returns no rows.
*/

