-- INSERT INTO ACTIVITY (PLAYER_ID, EVENT_DATE, DEVICE_ID, GAMES_PLAYED) VALUES (1, '2020-01-01', 202, 3);

-- In that modified scenario, Q2 would return both rows (because both get RANK() = 1), whereas Q1’s behavior might differ depending on how the SQL engine treats the tuple IN comparison with duplicate tuples. However, under the current schema constraints no such counterexample is possible.

