schema:
CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR,
    FOLLOWER VARCHAR,
    PRIMARY KEY (FOLLOWEE, FOLLOWER)
);

counterexample:
-- Counterexample: assume duplicates are allowed (i.e. ignore the PK constraint)
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('a', 'b');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('a', 'c');
-- Duplicate row: a followed by c appears again
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('a', 'c');
-- To ensure that 'a' appears also as a follower (so that it qualifies in both queries)
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('d', 'a');

-- For this data:
-- Q1 (which groups by FOLLOWEE) considers all rows where FOLLOWEE is in (SELECT FOLLOWER FROM FOLLOW).
-- Here the subquery returns { 'b', 'c', 'a' } so both 'a' and 'd' (from the row with followee 'd') are candidates, but only 'a' appears as FOLLOWEE in more than one row.
-- Grouping by FOLLOWEE, Q1 returns for user 'a' a count of 3 (one from the ('a','b') row and two from the ('a','c') rows).

-- Q2 does an inner join: it finds rows F1 where F1.FOLLOWER = some user X that also appears as FOLLOWEE in some F2 row. Here, note that 'a' appears as follower in the (d, 'a') row. Then joining on F2 (rows where FOLLOWEE = 'a') returns the two rows for user 'a' (even though one is a duplicate, COUNT(DISTINCT F2.FOLLOWER) returns count 2, the distinct followers being 'b' and 'c').
-- Thus Q2 returns for user 'a' a count of 2.

