INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (2, 1, NULL, '2020-03-01', 600);

-- Outcome:
-- Q1: For Bob, the count of red orders is 0 so Bob is returned. Alice is omitted because she has a red order.
-- Q2: The subquery returns {1, NULL}. Since the presence of a NULL in the set makes the NOT IN comparison evaluate to UNKNOWN for every row, Q2 returns no rows.

