INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (3, 15, 105, '2019-05-01', 6, 200);

-- Both Q1 and Q2 will return only PRODUCT 1 in this test data.

