CREATE TABLE CUSTOMER (
    ID INT PRIMARY KEY,
    NAME VARCHAR,
    REFEREE_ID INT,
    FOREIGN KEY (REFEREE_ID) REFERENCES CUSTOMER(ID)
);

counterexample:
-- No counterexample exists because the two queries are equivalent. 
-- For demonstration, here are some sample INSERT statements that confirm identical outputs:
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (1, 'Alice', NULL);
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (2, 'Bob', NULL);
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (3, 'Charlie', 1);
INSERT INTO CUSTOMER (ID, NAME, REFEREE_ID) VALUES (4, 'David', 2);

-- In this test data, Q1 and Q2 both return the names 'Alice', 'Charlie' because:
-- • For Alice, REFEREE_ID is NULL, so both queries include her.
-- • For Bob (ID=2), Q1 is not run because his REFEREE_ID is NULL and his own row isn’t retrieved (unless he is selected by other criteria) but he is only used as a referee.
-- • For Charlie, REFEREE_ID = 1 which is not 2, so he is included.
-- • For David, REFEREE_ID = 2, so he is excluded.

-- Thus, even though sample data is provided, no counterexample exists where the outputs differ.

-- first insert two products
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'InRangeProd', 100);
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'MixedProd', 200);

-- now insert sales for product 1 (only in–window sales)
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 10, 100, '2019-02-15', 1, 100);

-- for product 2 insert one in–window sale and one out–of–window sale
INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (2, 20, 200, '2019-02-15', 1, 200);
